/**
 * Browser shim for @mysten/sui/graphql/schemas/latest
 *
 * The `graphql` tagged template from that package is generated by graphql-codegen
 * and is purely a TypeScript type-level construct — at runtime it simply returns
 * its input. The Sui GraphQL client accepts plain strings as queries, so this
 * no-op implementation is fully compatible.
 *
 * This file is aliased in vite.config.ts so the SDK can be bundled for the browser.
 */

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export function graphql(query: TemplateStringsArray | string, ...values: any[]): any {
	if (typeof query === 'string') return query
	// Tagged template literal call: reconstruct the string
	return (query as TemplateStringsArray).reduce(
		(acc, str, i) => acc + (values[i - 1] ?? '') + str,
	)
}
